//! NEP-297 standard events.
//!
//! Events are emitted as `EVENT_JSON:{...}` logs and reflect actual state
//! transitions only. Event names use `snake_case` as generated by the
//! SDK's `#[near(event_json)]` derive (e.g. `VendorRegistered` ->
//! `"vendor_registered"`).

use near_sdk::json_types::U128;
use near_sdk::{near, AccountId};

#[near(event_json(standard = "nep297"))]
#[derive(Debug)]
pub enum InvoiceGuardEvent {
    /// Treasury funded via `fund()`; `amount` is the attached deposit.
    #[event_version("1.0.0")]
    TreasuryFunded { amount: U128, ledger_balance: U128 },
    /// Admin changed the authorized agent account.
    #[event_version("1.0.0")]
    AgentChanged { agent: AccountId },
    /// Admin changed the per-payment maximum.
    #[event_version("1.0.0")]
    PaymentLimitChanged { max_payment: U128 },
    /// Admin changed the daily spending limit.
    #[event_version("1.0.0")]
    DailyLimitChanged { daily_limit: U128 },
    /// Admin changed the reserve floor.
    #[event_version("1.0.0")]
    ReserveFloorChanged { reserve_floor: U128 },
    /// Admin changed the manual-request approval window.
    #[event_version("1.0.0")]
    RequestTtlChanged { ttl_seconds: u64 },
    /// Payments paused by admin.
    #[event_version("1.0.0")]
    ContractPaused {},
    /// Payments unpaused by admin.
    #[event_version("1.0.0")]
    ContractUnpaused {},
    /// Vendor registered with an Ed25519 key and payout account.
    #[event_version("1.0.0")]
    VendorRegistered { vendor_id: AccountId, payout_account: AccountId },
    /// Vendor payout account changed (affects future payments only).
    #[event_version("1.0.0")]
    VendorPayoutChanged { vendor_id: AccountId, payout_account: AccountId },
    /// Vendor signing key rotated (old-key signatures become invalid).
    #[event_version("1.0.0")]
    VendorKeyRotated { vendor_id: AccountId },
    /// Vendor activated.
    #[event_version("1.0.0")]
    VendorActivated { vendor_id: AccountId },
    /// Vendor deactivated; its invoices are refused until reactivated.
    #[event_version("1.0.0")]
    VendorDeactivated { vendor_id: AccountId },
    /// A vendor invoice passed all checks; nonce consumed, funds reserved.
    #[event_version("1.0.0")]
    InvoiceAccepted {
        payment_id: u64,
        vendor_id: AccountId,
        nonce: u64,
        amount: U128,
        recipient: AccountId,
    },
    /// An agent submitted a manual payment request (pending approval).
    #[event_version("1.0.0")]
    ManualPaymentRequested { payment_id: u64, vendor_id: AccountId, amount: U128 },
    /// Admin approved the exact stored manual request; funds reserved.
    #[event_version("1.0.0")]
    ManualPaymentApproved {
        payment_id: u64,
        vendor_id: AccountId,
        amount: U128,
        recipient: AccountId,
    },
    /// Admin rejected a pending manual request.
    #[event_version("1.0.0")]
    ManualPaymentRejected { payment_id: u64 },
    /// A pending manual request expired (lazy cleanup).
    #[event_version("1.0.0")]
    ManualPaymentExpired { payment_id: u64 },
    /// Payment entered PROCESSING; transfer scheduled.
    #[event_version("1.0.0")]
    PaymentProcessing {
        payment_id: u64,
        vendor_id: AccountId,
        amount: U128,
        recipient: AccountId,
    },
    /// Transfer succeeded; ledger debited, day spending recorded.
    #[event_version("1.0.0")]
    PaymentPaid { payment_id: u64, vendor_id: AccountId, amount: U128 },
    /// Transfer failed; reservation released, ledger unchanged.
    #[event_version("1.0.0")]
    PaymentFailed { payment_id: u64, vendor_id: AccountId, amount: U128 },
}
